#include <algorithm>
using namespace std;

class Solution {
public:
    int nthMagicalNumber(int N, int A, int B) {
        const int mod = 1e9 + 7;
        int lcm = A * B / gcd(A, B);

        long long left = min(A, B), right = (long long)N * min(A, B);

        while (left < right) {
            long long mid = left + (right - left) / 2;
            if (mid / A + mid / B - mid / lcm >= N) right = mid;
            else left = mid + 1;
        }

        return (int)(left % mod);
    }
};
